import React, { useState, useEffect, useRef, useCallback, useMemo } from 'react';
import ReactDOM from 'react-dom/client';
import * as XLSX from 'xlsx';

const PLOTTER_UNITS_PER_MM = 40; 
const SECTION_GAP = 500; 

interface CornerRadii {
    tl?: number;
    tr?: number;
    br?: number;
    bl?: number;
}

interface AppItem {
    id: string;
    internalOrderNumber: string;
    productCode: string;
    notes: string;
    material: string;
    color: string;
    w: number;
    h: number;
    qty: number;
    cornerRadius: CornerRadii;
    isCustom: boolean;
    classification: string;
    rotated?: boolean;
    rotationAngle?: number; 
    x?: number;
    y?: number;
    originalId?: string;
    pathData?: string; 
    isSupplement?: boolean; 
    pageIndex?: number; 
}

interface PageLayout {
    pageIndex: number;
    boxes: AppItem[];
    w: number;
    h: number; 
}

interface FullLayout {
    pages: PageLayout[];
    totalW: number;
    totalH: number; 
}

const EXPORT_COLUMNS = [
    { key: 'index', label: '序号' },
    { key: 'internalOrderNumber', label: '内部订单号' },
    { key: 'productCode', label: '商品编码' },
    { key: 'notes', label: '卖家备注' },
    { key: 'material', label: '材质' },
    { key: 'color', label: '颜色' },
    { key: 'w', label: '宽(mm)' },
    { key: 'h', label: '高(mm)' },
    { key: 'rotated', label: '旋转' },
    { key: 'cost', label: '成本价' },
    { key: 'page', label: '分段' }
];

const PRESET_SUPPLEMENTS: Partial<AppItem>[] = [
    { w: 200, h: 250, cornerRadius: { tl: 10, tr: 10, br: 10, bl: 10 }, internalOrderNumber: '预设 200x250' },
    { w: 300, h: 450, cornerRadius: { tl: 150, tr: 150, br: 150, bl: 150 }, internalOrderNumber: '预设 300x450' },
    { w: 400, h: 800, cornerRadius: { tl: 0, tr: 0, br: 0, bl: 0 }, internalOrderNumber: '预设 400x800' },
    { w: 500, h: 1000, cornerRadius: { tl: 0, tr: 0, br: 0, bl: 0 }, internalOrderNumber: '预设 500x1000' },
    { w: 600, h: 1200, cornerRadius: { tl: 0, tr: 0, br: 0, bl: 0 }, internalOrderNumber: '预设 600x1200' },
];

const stringToColor = (str: string) => {
    let hash = 0;
    for (let i = 0; i < str.length; i++) {
        hash = str.charCodeAt(i) + ((hash << 5) - hash);
    }
    const c = (hash & 0x00FFFFFF).toString(16).toUpperCase();
    return '#' + '00000'.substring(0, 6 - c.length) + c;
};

// --- Packing Algorithm ---
interface FreeRect { x: number; y: number; w: number; h: number; }
const MAX_INT = Number.MAX_SAFE_INTEGER;
type SortStrategy = 'AREA_DESC' | 'LONGSIDE_DESC' | 'WIDTH_DESC' | 'ORDER_GROUP' | 'CUSTOM';
type Heuristic = 'BSSF' | 'BLSF' | 'BAF';

const packLayout = (
    itemsInput: AppItem[], 
    containerWidth: number, 
    maxContainerHeight: number,
    spacing: number,
    allowRotation: boolean,
    useRandom: boolean,
    sortStrategy: SortStrategy = 'AREA_DESC',
    heuristic: Heuristic = 'BSSF',
    groupByOrder: boolean = false
): FullLayout => {
    const items = itemsInput.map(i => ({...i}));
    if (sortStrategy === 'AREA_DESC') items.sort((a, b) => (b.w * b.h) - (a.w * a.h));
    else if (sortStrategy === 'ORDER_GROUP' || groupByOrder) {
        items.sort((a, b) => {
            const orderComp = a.internalOrderNumber.localeCompare(b.internalOrderNumber, 'zh-CN', { numeric: true });
            if (orderComp !== 0) return orderComp;
            return (b.w * b.h) - (a.w * a.h);
        });
    }

    const pages: PageLayout[] = [];
    let remainingItems = items;
    let pageIndex = 1;

    while (remainingItems.length > 0) {
        const result = packOnePage(remainingItems, containerWidth, maxContainerHeight, spacing, allowRotation, useRandom, heuristic, pageIndex);
        pages.push(result.page);
        remainingItems = result.unpacked;
        pageIndex++;
        if (result.page.boxes.length === 0 && remainingItems.length > 0) remainingItems.shift(); 
    }
    return { pages, totalW: containerWidth, totalH: pages.reduce((sum, p) => sum + p.h, 0) };
};

const packOnePage = (itemsSource: AppItem[], containerWidth: number, maxHeight: number, spacing: number, allowRotation: boolean, useRandom: boolean, heuristic: Heuristic, pageIndex: number) => {
    const effectiveMaxH = (maxHeight > 0) ? maxHeight : MAX_INT;
    let freeRects: FreeRect[] = [{ x: 0, y: 0, w: containerWidth, h: effectiveMaxH }];
    const packed: AppItem[] = [];
    const itemsToProcess = [...itemsSource];

    const isIntersecting = (r1: FreeRect, r2: any) => !(r2.x >= r1.x + r1.w || r2.x + r2.w <= r1.x || r2.y >= r1.y + r1.h || r2.y + r2.h <= r1.y);
    const pruneFreeRects = () => {
        for(let i = 0; i < freeRects.length; i++) {
            for(let j = i + 1; j < freeRects.length; j++) {
                if (freeRects[j].x <= freeRects[i].x && freeRects[j].y <= freeRects[i].y && freeRects[j].x + freeRects[j].w >= freeRects[i].x + freeRects[i].w && freeRects[j].y + freeRects[j].h >= freeRects[i].y + freeRects[i].h) { freeRects.splice(i, 1); i--; break; }
                if (freeRects[i].x <= freeRects[j].x && freeRects[i].y <= freeRects[j].y && freeRects[i].x + freeRects[i].w >= freeRects[j].x + freeRects[j].w && freeRects[i].y + freeRects[i].h >= freeRects[j].y + freeRects[j].h) { freeRects.splice(j, 1); j--; }
            }
        }
    };

    while (itemsToProcess.length > 0) {
        let bestScore = MAX_INT;
        let bestMove = null;
        for (let i = 0; i < itemsToProcess.length; i++) {
            const item = itemsToProcess[i];
            for (let j = 0; j < freeRects.length; j++) {
                const rect = freeRects[j];
                const check = (w: number, h: number, rot: boolean) => {
                    const rw = w + spacing, rh = h + spacing;
                    if (rw <= rect.w && rh <= rect.h) {
                        let score = Math.min(rect.w - rw, rect.h - rh);
                        if (useRandom) score += Math.random() * 10;
                        if (score < bestScore) { bestScore = score; bestMove = { itemIdx: i, rectIdx: j, rotated: rot }; }
                    }
                };
                check(item.w, item.h, false);
                if (allowRotation) check(item.h, item.w, true);
            }
        }

        if (bestMove) {
            const item = itemsToProcess.splice(bestMove.itemIdx, 1)[0];
            const rect = freeRects[bestMove.rectIdx];
            const w = bestMove.rotated ? item.h : item.w;
            const h = bestMove.rotated ? item.w : item.h;
            const placedBox = { ...item, x: rect.x, y: rect.y, rotated: bestMove.rotated, rotationAngle: bestMove.rotated ? 90 : 0, pageIndex };
            packed.push(placedBox);
            const pr = { x: rect.x, y: rect.y, w: w + spacing, h: h + spacing };
            const newRects: FreeRect[] = [];
            for (let r of freeRects) {
                if (isIntersecting(r, pr)) {
                    if (pr.y > r.y) newRects.push({ x: r.x, y: r.y, w: r.w, h: pr.y - r.y });
                    if (pr.y + pr.h < r.y + r.h) newRects.push({ x: r.x, y: pr.y + pr.h, w: r.w, h: r.y + r.h - (pr.y + pr.h) });
                    if (pr.x > r.x) newRects.push({ x: r.x, y: r.y, w: pr.x - r.x, h: r.h });
                    if (pr.x + pr.w < r.x + r.w) newRects.push({ x: pr.x + pr.w, y: r.y, w: r.x + r.w - (pr.x + pr.w), h: r.h });
                } else newRects.push(r);
            }
            freeRects = newRects; pruneFreeRects();
        } else break;
    }
    return { page: { pageIndex, boxes: packed, w: containerWidth, h: packed.reduce((max, b) => Math.max(max, b.y + (b.rotated ? b.w : b.h)), 0) }, unpacked: itemsToProcess };
};

// --- App Component ---
const App = () => {
    const [stagedItems, setStagedItems] = useState<AppItem[]>([]);
    const [materialWidth, setMaterialWidth] = useState(1500);
    const [spacing, setSpacing] = useState(10);
    const [layout, setLayout] = useState<FullLayout | null>(null);
    const [currentStep, setCurrentStep] = useState(1);
    const [isLoading, setIsLoading] = useState(false);
    const [groupedOrders, setGroupedOrders] = useState<Record<string, AppItem[]>>({});
    const [selectedGroupKey, setSelectedGroupKey] = useState<string | null>(null);
    const [canvasTransform, setCanvasTransform] = useState({ scale: 1, x: 0, y: 0 });

    const canvasRef = useRef<HTMLCanvasElement>(null);
    const containerRef = useRef<HTMLDivElement>(null);

    // --- Persistence ---
    const exportProject = () => {
        const data = JSON.stringify({ stagedItems, materialWidth, spacing, layout, groupedOrders });
        const blob = new Blob([data], { type: 'application/json' });
        const a = document.createElement('a');
        a.href = URL.createObjectURL(blob);
        a.download = `nesting-project-${new Date().getTime()}.json`;
        a.click();
    };

    const importProject = (e: React.ChangeEvent<HTMLInputElement>) => {
        const file = e.target.files?.[0];
        if (!file) return;
        const reader = new FileReader();
        reader.onload = (ev) => {
            try {
                const data = JSON.parse(ev.target?.result as string);
                setStagedItems(data.stagedItems || []);
                setMaterialWidth(data.materialWidth || 1500);
                setSpacing(data.spacing || 10);
                setLayout(data.layout || null);
                setGroupedOrders(data.groupedOrders || {});
                setCurrentStep(data.layout ? 3 : 2);
            } catch (err) { alert('项目文件格式不正确'); }
        };
        reader.readAsText(file);
    };

    // --- Parsing Logic ---
    const processFile = async (e: React.ChangeEvent<HTMLInputElement>) => {
        const file = e.target.files?.[0];
        if (!file) return;
        setIsLoading(true);
        const reader = new FileReader();
        reader.onload = (ev) => {
            try {
                const data = new Uint8Array(ev.target?.result as ArrayBuffer);
                const workbook = XLSX.read(data, { type: 'array' });
                const ws = workbook.Sheets[workbook.SheetNames[0]];
                const json = XLSX.utils.sheet_to_json(ws, { header: 1 }) as any[][];

                const headers = json[0];
                const orderIdx = headers.indexOf('内部订单号');
                const codeIdx = headers.indexOf('商品编码');
                const noteIdx = headers.indexOf('订单备注');
                const qtyIdx = headers.indexOf('数量');

                const parsed: AppItem[] = [];
                json.slice(1).forEach((row, i) => {
                    const notes = String(row[noteIdx] || '');
                    const code = String(row[codeIdx] || '');
                    const fullText = notes + code;

                    // Regex for dimensions like 100*200, 100x200, 直径50
                    const dimMatch = fullText.match(/(\d+\.?\d*)\s*[x*×]\s*(\d+\.?\d*)/);
                    const diaMatch = fullText.match(/(?:直径|D)\s*(\d+\.?\d*)/i);

                    let w = 0, h = 0;
                    if (dimMatch) { w = parseFloat(dimMatch[1]); h = parseFloat(dimMatch[2]); }
                    else if (diaMatch) { w = parseFloat(diaMatch[1]); h = w; }

                    if (w > 0) {
                        parsed.push({
                            id: `item-${i}-${Date.now()}`,
                            internalOrderNumber: String(row[orderIdx] || '未知'),
                            productCode: code,
                            notes: notes,
                            material: fullText.includes('绒') ? '单面绒' : '皮革',
                            color: fullText.includes('白') ? '白色' : '灰色',
                            w: w < 50 ? w * 10 : w, // Auto convert cm to mm
                            h: h < 50 ? h * 10 : h,
                            qty: parseInt(row[qtyIdx]) || 1,
                            cornerRadius: { tl: notes.includes('圆角') ? 10 : 0 },
                            isCustom: notes.includes('定制'),
                            classification: notes.includes('圆角') ? '圆角' : '常规'
                        });
                    }
                });
                setStagedItems(parsed);
                setCurrentStep(2);
            } catch (err) { alert('读取文件失败'); }
            finally { setIsLoading(false); }
        };
        reader.readAsArrayBuffer(file);
    };

    const runNesting = () => {
        if (!selectedGroupKey || !groupedOrders[selectedGroupKey]) return;
        const items = groupedOrders[selectedGroupKey];
        const res = packLayout(items, materialWidth, 0, spacing, true, false, 'AREA_DESC');
        setLayout(res);
    };

    const confirmGrouping = () => {
        const groups: Record<string, AppItem[]> = {};
        stagedItems.forEach(it => {
            const key = `${it.material}/${it.color}`;
            if (!groups[key]) groups[key] = [];
            for (let i = 0; i < it.qty; i++) groups[key].push({ ...it, id: `${it.id}-${i}` });
        });
        setGroupedOrders(groups);
        setSelectedGroupKey(Object.keys(groups)[0]);
        setCurrentStep(3);
    };

    // --- Drawing ---
    useEffect(() => {
        if (!layout || !canvasRef.current) return;
        const ctx = canvasRef.current.getContext('2d')!;
        const scale = (containerRef.current?.clientWidth || 800) / layout.totalW;
        canvasRef.current.width = layout.totalW * scale;
        canvasRef.current.height = (layout.totalH + (layout.pages.length * 100)) * scale;

        ctx.clearRect(0, 0, canvasRef.current.width, canvasRef.current.height);
        ctx.save();
        ctx.scale(scale, scale);

        let yOffset = 0;
        layout.pages.forEach(p => {
            ctx.strokeStyle = '#ddd';
            ctx.strokeRect(0, yOffset, p.w, p.h);
            p.boxes.forEach(b => {
                const bw = b.rotated ? b.h : b.w;
                const bh = b.rotated ? b.w : b.h;
                ctx.fillStyle = stringToColor(b.internalOrderNumber);
                ctx.globalAlpha = 0.3;
                ctx.fillRect(b.x, b.y + yOffset, bw, bh);
                ctx.globalAlpha = 1;
                ctx.strokeStyle = '#333';
                ctx.lineWidth = 1;
                ctx.strokeRect(b.x, b.y + yOffset, bw, bh);

                if (bw > 50) {
                    ctx.fillStyle = '#000';
                    ctx.font = '12px Arial';
                    ctx.fillText(b.internalOrderNumber.slice(-4), b.x + 2, b.y + yOffset + 15);
                }
            });
            yOffset += p.h + 100;
        });
        ctx.restore();
    }, [layout]);

    return (
        <div style={{ padding: '20px', maxWidth: '1400px', margin: '0 auto' }}>
            <div style={{ display: 'flex', justifyContent: 'space-between', alignItems: 'center', borderBottom: '2px solid #eee', paddingBottom: '10px' }}>
                <h1 style={{ color: '#007bff' }}>智能排版助手 V2.0 (本地运行版)</h1>
                <div style={{ display: 'flex', gap: '10px' }}>
                    <button className="btn" onClick={exportProject}>导出项目</button>
                    <label className="btn" style={{ cursor: 'pointer' }}>
                        导入项目 <input type="file" hidden onChange={importProject} />
                    </label>
                </div>
            </div>

            {currentStep === 1 && (
                <div className="card">
                    <h2>第一步：初始化</h2>
                    <div style={{ padding: '40px', border: '2px dashed #ccc', textAlign: 'center' }}>
                        <p>请上传您的订单表格 (Excel)</p>
                        <input type="file" accept=".xlsx" onChange={processFile} disabled={isLoading} />
                        {isLoading && <p>正在处理解析中...</p>}
                    </div>
                </div>
            )}

            {currentStep === 2 && (
                <div className="card">
                    <h2>第二步：数据审核</h2>
                    <table style={{ width: '100%', borderCollapse: 'collapse' }}>
                        <thead>
                            <tr style={{ background: '#f5f5f5' }}>
                                <th>订单号</th><th>尺寸 (WxH)</th><th>材质/颜色</th><th>数量</th><th>操作</th>
                            </tr>
                        </thead>
                        <tbody>
                            {stagedItems.map(it => (
                                <tr key={it.id} style={{ borderBottom: '1px solid #eee' }}>
                                    <td>{it.internalOrderNumber}</td>
                                    <td>{it.w} x {it.h}</td>
                                    <td>{it.material} / {it.color}</td>
                                    <td>{it.qty}</td>
                                    <td><button onClick={() => setStagedItems(prev => prev.filter(i => i.id !== it.id))}>删除</button></td>
                                </tr>
                            ))}
                        </tbody>
                    </table>
                    <button className="btn-primary" style={{ marginTop: '20px' }} onClick={confirmGrouping}>确认并去排版</button>
                </div>
            )}

            {currentStep === 3 && (
                <div className="card">
                    <h2>第三步：排版与导出</h2>
                    <div style={{ display: 'flex', gap: '20px', marginBottom: '20px' }}>
                        <div style={{ flex: 1 }}>
                            <label>选择物料组：</label>
                            <select value={selectedGroupKey || ''} onChange={e => setSelectedGroupKey(e.target.value)}>
                                {Object.keys(groupedOrders).map(k => <option key={k} value={k}>{k} ({groupedOrders[k].length}件)</option>)}
                            </select>
                            <button className="btn-primary" onClick={runNesting} style={{ marginLeft: '10px' }}>开始排版</button>
                        </div>
                        <div style={{ display: 'flex', gap: '10px' }}>
                            <input type="number" value={materialWidth} onChange={e => setMaterialWidth(Number(e.target.value))} placeholder="宽" />
                            <input type="number" value={spacing} onChange={e => setSpacing(Number(e.target.value))} placeholder="间距" />
                        </div>
                    </div>

                    <div ref={containerRef} style={{ background: '#eee', minHeight: '500px', borderRadius: '8px', overflow: 'hidden' }}>
                        <canvas ref={canvasRef} style={{ display: 'block' }} />
                    </div>
                </div>
            )}

            <style>{`
                .card { background: white; padding: 20px; border-radius: 8px; box-shadow: 0 2px 8px rgba(0,0,0,0.1); margin-top: 20px; }
                .btn { padding: 8px 16px; border: 1px solid #ccc; background: white; border-radius: 4px; cursor: pointer; }
                .btn:hover { background: #f9f9f9; }
                .btn-primary { padding: 10px 24px; background: #007bff; color: white; border: none; border-radius: 4px; cursor: pointer; font-weight: bold; }
                .btn-primary:hover { background: #0056b3; }
                table th, table td { padding: 12px; text-align: left; }
                input[type="number"], select { padding: 8px; border: 1px solid #ddd; border-radius: 4px; }
            `}</style>
        </div>
    );
};

const root = ReactDOM.createRoot(document.getElementById('root')!);
root.render(<App />);
